// EDITE AQUI as duas constantes antes de usar:
const BASE_URL = "http://localhost:3333"; // URL pública do backend do motor de agenda
const EVOLUTION_URL = "http://localhost:8080"; // URL da sua instância Evolution API

const body = $input.first().json.body ?? $input.first().json;
const dados = body.data ?? body;
const key = dados.key ?? {};
const mensagem = dados.message ?? {};

// Convenção: o nome da instância Evolution é o slug da empresa no motor de agenda.
const slug = body.instance;
const telefoneRaw = key.remoteJid ?? "";
const telefone = telefoneRaw.replace("@s.whatsapp.net", "").replace(/\D/g, "");
const texto = mensagem.conversation ?? mensagem.extendedTextMessage?.text ?? "";
const fromMe = Boolean(key.fromMe);

return [{ json: { slug, telefone, texto, fromMe, baseUrl: BASE_URL, evolutionUrl: EVOLUTION_URL } }];
